import inspect


class Agent:
    def __init__(self, name, instructions, tools=None, handoffs=None):
        self.name = name
        self.instructions = instructions
        self.tools = dict(tools or {})
        self.handoffs = list(handoffs or [])


def transfer_name(agent):
    return "transfer_to_" + agent.name.lower()


def catalog(agent):
    entries = []
    for name, entry in agent.tools.items():
        if isinstance(entry, Agent):
            description = entry.instructions
        else:
            doc = inspect.getdoc(entry) or ""
            description = doc.splitlines()[0].strip() if doc else ""
        entries.append({"name": name, "description": description})
    for target in agent.handoffs:
        entries.append({
            "name": transfer_name(target),
            "description": f"Hand the conversation off to the {target.name} agent.",
        })
    return entries


def run(agent, message, planner, session=None, guardrails=(), max_turns=8):
    history = list(session) if session is not None else []
    history.append({"role": "user", "content": message})

    def finish(final_output, turns, events, tripwire=None):
        if final_output is not None:
            history.append({"role": "assistant", "content": final_output})
        if session is not None:
            session[:] = history
        return {"final_output": final_output, "last_agent": active.name,
                "turns": turns, "events": events, "history": history,
                "tripwire": tripwire}

    active = agent
    for guard in guardrails:
        reason = guard(message)
        if reason:
            return finish(None, 0, [], tripwire=reason)

    events = []
    for turn in range(1, max_turns + 1):
        decision = planner(active, catalog(active), history)
        if "final" in decision:
            return finish(decision["final"], turn, events)
        name = decision.get("tool")
        args = dict(decision.get("args") or {})

        targets = {transfer_name(t): t for t in active.handoffs}
        if name in targets:
            target = targets[name]
            events.append({"kind": "handoff", "from": active.name, "to": target.name})
            active = target
            continue

        entry = active.tools.get(name)
        if entry is None:
            events.append({"kind": "error", "tool": name})
            history.append({"role": "tool", "content": f"Error: unknown tool {name!r}"})
            continue
        if isinstance(entry, Agent):
            inner = run(entry, args.get("input", ""), planner, max_turns=max_turns)
            result = inner["final_output"]
            events.append({"kind": "agent_as_tool", "agent": entry.name,
                           "result": result})
        else:
            result = entry(**args)
            events.append({"kind": "tool", "tool": name, "result": result})
        history.append({"role": "tool", "content": str(result)})

    return finish(None, max_turns, events)
